Method.Implementation:
set tSc = $$$OK

 set stat = ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(cmd, "/itf-share/itf-tmp/lpjnaras/TpManage.out", "/itf-share/itf-tmp/lpjnaras/TpManage.err")

 if (stat = 0)
 {
	 Do outFile.WriteLine( "Created new TP files from Edifecs")
 	// Clean the <ApplicationSettings>
 	// set cleanCmd = "/home/cacheusr/TpManage/edifecs/cleanCmd"
 	// Do ##class(IHC.ITF.ITFCOMMON.Utility).ExecuteShellCmd(cleanCmd, "/itf-share/itf-tmp/lpjnaras/TpManage.out", "/itf-share/itf-tmp/lpjnaras/TpManage.err")
 }
 else
 {
	 set tSc = $$$ERROR($$$GeneralError, "Error in " _ cmd)

 }
 return tSc

 set tSC = $$$OK
 set dtTm = $ZDATETIME($HOROLOG,3, 1)
 set separator = "~! "
 SET todayNum=$PIECE($HOROLOG,",",1)
 set sqlUsr = "hsadmin"

 if (##class(%File).Exists(flNm))
 {
     set line = 1
	 set fileObj = ##class(%File).%New(flNm)

	 set tSC = fileObj.Open("R")
	 set numRecs = 0, numDup = 0, numIns = 0, numErr = 0
	 while 'fileObj.AtEnd {
		 set text = fileObj.ReadLine(,.sc, .eol)
		 if $$$ISERR(sc) 
		 {
			 Do outFile.WriteLine( "End of File: " _sc _ ", " _ eol)
			 QUIT
		 }
		 else
		 {

			 if ($L(text) <= 0)
			 {
			   continue
			 } 
			 set numRecs = numRecs + 1

 			 //Trading Partner
		     // Do outFile.WriteLine( text _", length: " _ $L(text, separator)
			 set modDt = $ZSTRIP($PIECE(text, separator, 29),"<>W")
			 set tpNm = $ZSTRIP($PIECE(text, separator, 2),"<>W")
			 if ((todayNum - $ZDATEH(modDt, 3)) > LastModifiedDate)
			 {
				 // Do outFile.WriteLine( tpNm _" modifed on " _ modDt)
			 }
			 else
			 {
			     Do outFile.WriteLine( "Insert or update: " _ tpNm)
				 set ediId = $ZSTRIP($PIECE(text, separator, 1),"<>W")

				 set typ = $ZSTRIP($PIECE(text, separator, 3),"<>W")
				 set tele = $ZSTRIP($PIECE(text, separator, 4),"<>W")
				 if (tele = "-")
				 {
					 set tele = "555-1212"
				 }
				 set em = $ZSTRIP($PIECE(text, separator, 5),"<>W")
				 if (em = "-")
				 {
					 set em = "TDB@"_tpNm
				 }

				 if ( (tpNm '= "") && (typ '= ""))
				 {
					 &SQL(INSERT INTO  IHC_ITF_ITFCOMMON_TPManage.TradingPartner 
					 (ContactEmail, ContactName, ContactPhone, 
					 CreateID, CreatedDtTM, LastmodDtTM, LastmodID, Name, Type, EdifecsId)
					 values(:em, 'TBD', :tele,:sqlUsr,:dtTm,:dtTm,:sqlUsr,:tpNm,:typ,:ediId))
					 if (SQLCODE = 0)
					 {
						 // Do outFile.WriteLine( "Inserted " _ tpNm _ " / " _typ)
						 set numIns = numIns + 1

						 set OutConn270RTAcks= $ZSTRIP($PIECE(text, separator, 7),"<>W")
						 set OutConn820Acks= $ZSTRIP($PIECE(text, separator, 8),"<>W")
						 set ElementSeparator= $ZSTRIP($PIECE(text, separator, 9),"<>W")
						 set ISACompElementSeparator= $ZSTRIP($PIECE(text, separator, 10),"<>W")
						 set OutConn271RT= $ZSTRIP($PIECE(text, separator, 11),"<>W")

						 set OutConn837DAcks= $ZSTRIP($PIECE(text, separator, 12),"<>W")
						 set OutConn278Acks= $ZSTRIP($PIECE(text, separator, 13),"<>W")
						 set OutConn276RTAcks= $ZSTRIP($PIECE(text, separator, 14),"<>W")
						 set OutConn277RT = $ZSTRIP($PIECE(text, separator, 15),"<>W")
						 set OutConn271B = $ZSTRIP($PIECE(text, separator, 16),"<>W")
						 set OutConn837PAcks= $ZSTRIP($PIECE(text, separator, 17),"<>W")
						 set AckUsag999RT= $ZSTRIP($PIECE(text, separator, 18),"<>W")
						 set OutConn270BAcks= $ZSTRIP($PIECE(text, separator, 19),"<>W")
						 set OutConn835= $ZSTRIP($PIECE(text, separator, 20),"<>W")
						 set OutConn277CA= $ZSTRIP($PIECE(text, separator, 21),"<>W")
						 set OutConn837IAcks= $ZSTRIP($PIECE(text, separator, 22),"<>W")
						 set AckUsage999= $ZSTRIP($PIECE(text, separator, 23),"<>W")
						 set OutConn277B= $ZSTRIP($PIECE(text, separator, 24),"<>W")
						 set AckUsageTA1= $ZSTRIP($PIECE(text, separator, 25),"<>W")
						 set AckUsageTA1RT= $ZSTRIP($PIECE(text, separator, 26),"<>W")
						 set OutConn276BAcks= $ZSTRIP($PIECE(text, separator, 27),"<>W")
						 set BatchingMode835= $ZSTRIP($PIECE(text, separator, 28),"<>W")

						  &SQL(INSERT INTO  IHC_ITF_ITFCOMMON_TPManage.CustomFields 
						 (EdicTpId, AckUsage999, AckUsage999RT, AckUsageTA1, AckUsageTA1RT, BatchingMode835, 
						 ElementSeparator, ISACompElementSeparator, OutConn270BAcks, OutConn270RTAcks, OutConn271B, 
						 OutConn271RT, OutConn276BAcks, OutConn276RTAcks, OutConn277B, OutConn277CA, OutConn277RT, 
						 OutConn278Acks, OutConn820Acks, OutConn835, OutConn837DAcks, OutConn837IAcks, OutConn837PAcks)
						 values(:ediId, :AckUsage999, :AckUsage999RT, :AckUsageTA1, :AckUsageTA1RT, :BatchingMode835, 
						  :ElementSeparator, :ISACompElementSeparator, :OutConn270BAcks, :OutConn270RTAcks, :OutConn271B, 
						  :OutConn271RT, :OutConn276BAcks, :OutConn276RTAcks, :OutConn277B, :OutConn277CA, :OutConn277RT, 
						  :OutConn278Acks, :OutConn820Acks, :OutConn835, :OutConn837DAcks, :OutConn837IAcks, :OutConn837PAcks
						  		 ))
						 if (SQLCODE = 0)
						 {
							 Do outFile.WriteLine( "Inserted CustomFields " _ AckUsage999 _ " / " _ediId)
						 }
						 else
						 {
							 Do outFile.WriteLine( SQLCODE _ ": " _ AckUsage999 _ " / " _ediId  _ " / " _ OutConn837PAcks)
						 }
					 }


					 elseif (SQLCODE = "-119")
					 {
						 // Do outFile.WriteLine( "Duplicate: " _ tpNm _ " / " _typ)
						 set numDup = numDup + 1

						 // Update
						 &SQL(UPDATE  IHC_ITF_ITFCOMMON_TPManage.TradingPartner 
							set ContactEmail = :em, ContactPhone = :tele, 
								LastmodDtTM = :dtTm, LastmodID = :sqlUsr,  
								Type=:typ, EdifecsId = :ediId where Name = :tpNm)

						Do outFile.WriteLine( "  UPDATE " _ tpNm _ " - SQLCODE: " _ SQLCODE	)	
					 }
					 else
					 {
						 Do outFile.WriteLine( "SQLCODE: " _ SQLCODE _ ", TP: " _ tpNm _ ", Type: " _typ)
						 set numErr= numErr + 1
					 }
				 }
				 else
				 {
					 Do outFile.WriteLine( "SKIP: " _ tpNm)
				 }

			 }
		 }
	 }
	 Do fileObj.Close()
	 Do outFile.WriteLine( "DONE processing " _ flNm _", # of rows: " _ numRecs _ ", inserted: " _ numIns _ ", Duplicates: " _ numDup _", errors: " _ numErr)
 }
 else
 {
	 Do outFile.WriteLine( "Can't open file: " _ flNm)
 }

 return tSC

  set separator = "~! "
  set dtTm = $ZDATETIME($HOROLOG,3, 1)
  SET todayNum=$PIECE($HOROLOG,",",1)
  set sqlUsr = "hsadmin"
  if (##class(%File).Exists(flNm))
  {
     set line = 1
	 set fileObj = ##class(%File).%New(flNm)

	 set tSC = fileObj.Open("R")
	 set numRecs = 0, numDup = 0, numIns = 0, numErr = 0
	 while 'fileObj.AtEnd {
		 set text = fileObj.ReadLine(,.sc, .eol)
		 if $$$ISERR(sc) 
		 {
			 Do outFile.WriteLine( "End of File: " _sc _ ", " _ eol)
			 QUIT
		 }
		 else
		 {	
		    if ($L(text) <= 0)
			{
			   continue
			}
			set ediId = $ZSTRIP($PIECE(text, separator, 1),"<>W")
		 	set tpId = $ZSTRIP($PIECE(text, separator, 2),"<>W")			
			set tpNm = $ZSTRIP($PIECE(text, separator, 3),"<>W")
			set typ = $ZSTRIP($PIECE(text, separator, 4),"<>W")

			set modDt = $ZSTRIP($PIECE(text, separator, 5),"<>W")

			 if ((todayNum - $ZDATEH(modDt, 3)) > LastModifiedDate)
			 {
				 // Do outFile.WriteLine( tpNm _" modifed on " _ modDt)
			 }
			 else
			 {

				// write !, "TPID -> " _ line _ ". " _ tpNm _ ":" _ typ
				set line = line + 1

				if ((tpNm = "") || (tpId = ""))
				{
					continue
				}

				set tradingPartnerId = ""
				&SQL(select ID into :tradingPartnerId FROM IHC_ITF_ITFCOMMON_TPManage.TradingPartner where Name = :tpNm)
				if SQLCODE '= 0
				{			
						Do outFile.WriteLine( "Error in finding TP for: " _  tpNm _ ", SQLCODE: " _ SQLCODE)

				}
				if (tradingPartnerId = "")
				{
						Do outFile.WriteLine( "ID for TP is empty " _ tpNm)

				}
				else
				{
					Set cm = ##class(IHC.ITF.ITFCOMMON.TPManage.TPIDS).%New()
					#dim tp As IHC.ITF.ITFCOMMON.TPManage.TradingPartner
					set tp = ##class(IHC.ITF.ITFCOMMON.TPManage.TradingPartner).%OpenId(tradingPartnerId)
					if ($IsObject(tp))
					{
						set cm.TPFK = tp
						set cm.TPID = $ZSTRIP(tpId,"<>WC")
						set cm.Type =  $SELECT(typ="":"BOTH",typ="null":"BOTH",1:typ) 
						set cm.EdifecsID = ediId
						set cm.Name = tpNm _ " TpId"
						set cm.CreatedDtTM = dtTm
						set cm.LastmodDtTM = dtTm
						set cm.LastmodID = sqlUsr
						set cm.CreateID = sqlUsr

						set stat = cm.%Save()


						if ($$$ISOK(stat))
						{
							set numIns = numIns + 1
							Do outFile.WriteLine( tpNm _ ", " _ tpId _ ", " _ tp _ ", " _ ediId _ ", " _ typ _ " - Saveed")
						}
						else
						{

							&SQL(SELECT count(*) into :numRows from IHC_ITF_ITFCOMMON_TPManage.TPIDS where TPID = :tpId)
							// Do outFile.WriteLine( SQLCODE _", #: " _ numRows)
							if ((SQLCODE = 0) && (numRows >= 1))
							{
								set numDup = numDup + 1
								if (numRows > 1)
								{
									Do outFile.WriteLine( " -***- Same TPID " _ tpId _ " exists multiple times ("_ numRows _ ") in IHC_ITF_ITFCOMMON_TPManage.TPIDS: " )

									set myquery = "SELECT NAME, EdifecsID FROM IHC_ITF_ITFCOMMON_TPManage.TPIDS where TPID = '" _ tpId _"'"
						    set tStatement = ##class(%SQL.Statement).%New()
							  set qStatus = tStatement.%Prepare(myquery)
							   if qStatus'=1 {write "%Prepare failed:" do $System.Status.DisplayError(qStatus) quit}
							  set rset = tStatement.%Execute()
							  while rset.%Next()
								{

										if SQLCODE = 0
										{			
												Do outFile.WriteLine( "  - Name: " _ rset.%Get("NAME") _ ", EdifecsID: " _ rset.%Get("EdifecsID"))
										}

								}

								}
								// Do outFile.WriteLine( "Duplicate TPID: " _ tpNm _ ", " _ tpId )
							}
							else
							{

								Do outFile.WriteLine( tpNm _ ", " _ tpId _ ", " _ tp _ ", " _ ediId _ ", " _ typ _ " - Save error: " _ stat)
								set numErr= numErr + 1
							}
						}
					}
					else
					{
						Do outFile.WriteLine( tpNm _" not found in IHC.ITF.ITFCOMMON.TPManage.TradingPartner")
					}
			 	}
			} 
		 }
	 }
 	 Do outFile.WriteLine( "Processed: " _ flNm)
	 DO fileObj.Close()

  }
  else
 {
	 Do outFile.WriteLine( "Can't open file: " _ flNm)
 }

  set separator = "~! "
  set dtTm = $ZDATETIME($HOROLOG,3, 1)
  set sqlUsr = "hsadmin"
  if (##class(%File).Exists(flNm))
  {
     set line = 1
	 set fileObj = ##class(%File).%New(flNm)

	 set tSC = fileObj.Open("R")
	 set numRecs = 0, numDup = 0, numIns = 0, numErr = 0
	 while 'fileObj.AtEnd {
		 set text = fileObj.ReadLine(,.sc, .eol)
		 if $$$ISERR(sc) 
		 {
			 Do outFile.WriteLine( "End of File: " _sc _ ", " _ eol)
			 QUIT
		 }
		 else
		 {
			 if ($L(text) <= 0)
			 {
			   continue
			 }
			 //TRANSACTIONTYPES

				 set trNm = $ZSTRIP($PIECE(text, separator, 1),"<>W")
