					 if (SQLCODE = 0)
					 {
						 // Do outFile.WriteLine( "Inserted " _ trNm _ " / " _type)
						 set numIns = numIns + 1
					 }
					 elseif (SQLCODE = "-119")
					 {
						 // Do outFile.WriteLine( "Duplicate: " _ trNm _ " / " _type)
						 set numDup = numDup + 1
					 }
					 else
					 {
						 Do outFile.WriteLine( SQLCODE _ ": " _ trNm _ " / " _type)
						 set numErr= numErr + 1
					 }
				 }
		 }
	 }
 	 Do outFile.WriteLine( "Processed: " _ flNm)
	 DO fileObj.Close()

  }
  else
 {
	 Do outFile.WriteLine( "Can't open file: " _ flNm)
 }

 set separator = "~! "
 set dtTm = $ZDATETIME($HOROLOG,3, 1)
 SET todayNum=$PIECE($HOROLOG,",",1)
 set sqlUsr = "hsadmin"
 set separtor = "~! "
 set numIds = 1
 set numTp = 0
 set numSave = 0
 set numDups = 0
 set numErr=0
 set line = 0
 set ttObj = ""
 set edifecsId = "", tt = "", notes = "", severity="", trans = ""
 set isaSender = "", isaReceiver ="", gsSender  = "", gsReceiver = ""
 set interchange = 0, functionalGroup = 0, transaction = 0, route = "", getCN = 0, level = "", ackStr = "", sepStr = "", batch835 = ""

  if (##class(%File).Exists(flNm))
  {
     set line = 1
	 set fileObj = ##class(%File).%New(flNm)

	 set tSC = fileObj.Open("R")
	 set numRecs = 0, numDup = 0, numIns = 0, numErr = 0
	 while 'fileObj.AtEnd {
		 set text = fileObj.ReadLine(,.sc, .eol)
		 if $$$ISERR(sc) 
		 {
			 Do outFile.WriteLine( "End of File: " _sc _ ", " _ eol)
			 QUIT
		 }
		 else
		 {
			 if ($L(text) <= 0)
			 {
			   continue
			 }
			 // --
			 set line = line + 1
			 if (($L(text) > 0) && ($F(text, "RESOLVEDCONFIGURATIONXML:<ApplicationSettings>") > 1))
			 {
				 set numIds = 0
				 set numTp = 1 + numTp

				 set interchange = 0, functionalGroup = 0, transaction = 0, route = "", trans = "", getCN = 0, level = "", ackStr = "", sepStr = ""
				 set cnStr = "", severity = "", isaSendEdicId = "", isaRecvEdicId = "", direction = "", type = "", usage = "", batch835 = ""

				 set edifecsId = $ZSTRIP($PIECE(text, separtor, 1),"<>W")
				 set sender = $ZSTRIP($PIECE(text, separtor, 3),"<>W")
				 set receiver = $ZSTRIP($PIECE(text, separtor, 4),"<>W")
				 set tpLnkNm = $ZSTRIP($PIECE(text, separtor, 2),"<>W")
				 set tt = $ZSTRIP($PIECE(text, separtor, 5),"<>W")
				 set notes = $ZSTRIP($PIECE(text, separtor, 6),"<>W")
				 set mode = $ZSTRIP($PIECE(text, separtor, 7),"<>W")
				 set modDt = $ZSTRIP($PIECE(text, separtor, 11),"<>W")
				 Do outFile.WriteLine(tpLnkNm _": " _ modDt _ " = " _ todayNum _ "-" _ $ZDATEH(modDt, 3))

				 if ((todayNum - $ZDATEH(modDt, 3)) > LastModifiedDate)
				 {
					 // Do outFile.WriteLine( tpLnkNm _" modifed on " _ modDt)
					 set tpLnkNm = ""
				 }
				 else
				 {

				  	set direction = $ZSTRIP($PIECE(text, separtor, 10),"<>W")

			 	 	&SQL(select ID into :id FROM IHC_ITF_ITFCOMMON_TPManage.TRADELINKS  where NAME = :tpLnkNm)

					if ((SQLCODE = 0) && (id > 0))
					{			
							//Do outFile.WriteLine( tpLnkNm _ "  ---- Duplicate in finding TRADELINKS " _ SQLCODE)
							set numDups = numDups + 1
							set numApSet = 0
							while (1)
							{
								set text = fileObj.ReadLine(,.sc, .eol)
								if $$$ISERR(sc) 
								 {
									 Do outFile.WriteLine( "End of File: " _sc _ ", " _ eol)
									 QUIT
								 }

								 else
								 {
									 if ($F(text, "<ApplicationSettings>") > 1)
									 {
										 set numApSet = 1
									 }
								 }
								 set line = line + 1
							 	if ( ($F(text, "</ApplicationSettings>") > 1) && (numApSet = 1) )
							 	{
								 	QUIT
							 	}
							}

							// Do outFile.WriteLine( "PROCESS: " _ fileObj.ReadLine(,.sc, .eol) _ " / " _ text _", " _ numApSet)
							continue

					}


			 	 	&SQL(select ID, TransactionSetId into :ttId, :trans FROM IHC_ITF_ITFCOMMON_TPManage.TRANSACTIONTYPES  where NAME = :tt)
					if SQLCODE '= 0
					{			
							Do outFile.WriteLine( tt _ " - Error in finding TRANSACTIONTYPES: " _ SQLCODE)
							QUIT

					}
					elseif (ttId = "")
					{
							Do outFile.WriteLine( "TRANSACTIONTYPES is empty " _ tt)

					}
					else
					{
						set ttObj = ##class(IHC.ITF.ITFCOMMON.TPManage.TRANSACTIONTYPES).%OpenId(ttId)
					}
					Do outFile.WriteLine( edifecsId _ ". " _tpLnkNm _"  --TT : " _ tt _", Direction: " _ direction)
				 }

			 }
			 elseif  (($F(text, "</ApplicationSettings>") > 1) && (severity '= "") )
			 {
				  set transaction = 0
				  if (tpLnkNm '= "")
				  {
				  	// INSERT --
				       Do outFile.WriteLine( edifecsId _". " _tpLnkNm _", TRANSACTIONTYPE: " _ tt _", Notes: " _ notes _", SeverityConfig: " _ severity _ ", ControlNumber: " _ cnStr)
				       Do outFile.WriteLine( "  - ISA: " _ isaSender _"->" _ isaReceiver _" / GS: " _gsSender _" -> "_gsReceiver  _", Route: " _ route _", Ack: " _ ackStr _", Separators: " _ sepStr )


						Set cm = ##class(IHC.ITF.ITFCOMMON.TPManage.TRADELINKS).%New()

						set tpId1 = ##class(IHC.ITF.ITFCOMMON.TPManage.TPIDS).%OpenId(isaReceiver)

						set cm.IsaReceiverId = tpId1
						set tpId2 = ##class(IHC.ITF.ITFCOMMON.TPManage.TPIDS).%OpenId(isaSender)

						set cm.IsaSenderId = tpId2
						set tpId3 = ##class(IHC.ITF.ITFCOMMON.TPManage.TPIDS).%OpenId(gsReceiver)

						set cm.GsReceiverId =  tpId3
						set tpId4 = ##class(IHC.ITF.ITFCOMMON.TPManage.TPIDS).%OpenId(gsSender)

						set cm.GsSenderId =  tpId4

						if ( ($IsObject(tpId1)) && ($IsObject(tpId2)) && ($IsObject(tpId3)) && ($IsObject(tpId4)) && ($IsObject(ttObj)) )
						{
							set cm.NAME = $ZSTRIP(tpLnkNm,"<>WC")
							set cm.EdifecsID = $ZSTRIP(edifecsId,"<>WC")
							set cm.TRANSTYPE = ttObj
							set cm.SNIP = 0
							if (severity ="L1-L2")
							{
								set cm.SNIP = 2
							}
							elseif (severity ="L1")
							{
								set cm.SNIP = 1
							}
							if (direction = 1)
							{
								set cm.Direction = "In"
							}
							else
							{
								set cm.Direction = "Out"
							}

							set cm.Active = 1
							set cm.Notes = $ZSTRIP(notes,"<>WC")
							set cm.Routing = $ZSTRIP($SELECT(route="":"NA",route=" ":"NA",1:route),"<>WC")
							set cm.ISAAck  = $ZSTRIP($PIECE(ackStr, ";", 1),"<>WC")
							set cm.GSAck  = $ZSTRIP($PIECE(ackStr, ";", 2),"<>WC")

							set cm.STAck  = "NEVER"
							if ($L(ackStr, ";") > 2)
							{
								set stStr = $ZSTRIP($PIECE(ackStr, ";", 3),"<>WC")

								if ($L(stStr) > 0)
								{
									set cm.STAck  = stStr
								}
							}

							set cm.Separators = "|*^:"
							if ($FIND(mode, "Batch") > 1)
							{
								set cm.Mode = "Batch" 
							}
							else
							{
								set cm.Mode = "RT" 
							}
							set cm.CreatedDtTM = dtTm
							set cm.LastmodDtTM = dtTm
							set cm.LastmodID = sqlUsr
							set cm.CreateID = sqlUsr
							set cm.ControlNumber = $ZSTRIP(cnStr,"<>WC")


						 	set stat = cm.%Save()

							if ($$$ISERR(stat))
							{

								Do $SYSTEM.Status.DisplayError(stat)

								Do outFile.WriteLine( " - Name: " _cm.NAME _ ", TT: " _ cm.TRANSTYPE _ ", Tp1: " _ tpId1.Name _ ",2: " _ tpId2.Name _ ",3: " _ tpId3.Name _ ",4: " _ tpId4.Name _", Mode: " _ cm.Mode)
								Do outFile.WriteLine( ", ACK: " _ cm.ISAAck _", " _ cm.GSAck _", " _ cm.STAck  _", ControlNumber: " _ cm.ControlNumber)
								Do outFile.WriteLine(  "EdifecsId: " _ cm.EdifecsID _", " _ cm.Notes _", Routing: " _ cm.Routing _" / " _ route _"; ")
								set numErr = numErr + 1

								&SQL(SELECT count(*) into :numRows from IHC_ITF_ITFCOMMON_TPManage.TRADELINKS where NAME = :tpLnkNm)
								// Do outFile.WriteLine( SQLCODE _", #: " _ numRows
								if ((SQLCODE = 0) && (numRows >= 1))
								{
									set numDup = numDup + 1
									if (numRows > 1)
									{
										Do outFile.WriteLine( " -***- Same Link exists multiple times in IHC_ITF_ITFCOMMON_TPManage.TRADELINKS: " _ tpLnkNm)
									}
									 Do outFile.WriteLine( "Duplicate Link: " _ tpLnkNm )
								}

							}

							// Insert Custom Properties
							Set tpLink = ##class(IHC.ITF.ITFCOMMON.TPManage.TRADELINKS).%OpenId(cm.%Id())

							If $IsObject(tpLink) {
								set kv1 = ##class(IHC.ITF.ITFCOMMON.TPManage.KeyValue).%New()
				   			 	set kv1.Key = "Separators"
				    			set kv1.Value = sepStr			    						    			
				    			set stat = tpLink.customProp.Insert(kv1)

				    			set kv2 = ##class(IHC.ITF.ITFCOMMON.TPManage.KeyValue).%New()
				    			set kv2.Key = "Severity"
				    			set kv2.Value = severity		    						    			
				    			set stat = tpLink.customProp.Insert(kv2)

				    			if (batch835 '= "")
				    			{
					    			set kv3 = ##class(IHC.ITF.ITFCOMMON.TPManage.KeyValue).%New()
					    			set kv3.Key = $PIECE(batch835, ":", 1)
					    			set kv3.Value = $PIECE(batch835, ":", 2)		    						    			
					    			set stat = tpLink.customProp.Insert(kv3)

				    			}

				    			if ($$$ISERR(stat))
								{
									Do outFile.WriteLine( "Error in INSERT KeyValue" _ stat)
									QUIT
								}
								// Do outFile.WriteLine( "IsModified: " _ tpLink.%IsModified() _", cnt # " _ tpLink.customProp.Count())


								set stat = tpLink.%Save()
								Do outFile.WriteLine( "IHC.ITF.ITFCOMMON.TPManage.TRADELINKS Id: " _ cm.%Id() _ " and KeyValues saved")

								if ($$$ISERR(stat))
								{
									Do outFile.WriteLine( "Error in UPDATE " _ stat)
									QUIT
								}
								set numSave = numSave + 1
							}

						}
						else
						{
							Do outFile.WriteLine( "ERROR - Name: " _tpLnkNm _ ", ID: " _ edifecsId _ ", TT: " _ tt _ "- Invalid TPIDs: " _ $IsObject(tpId1) _", " _ $IsObject(tpId2) _", " _ $IsObject(tpId3) _", " _ $IsObject(tpId4) _", " _ $IsObject(ttObj))
							set numErr = numErr + 1
						}
				  }

			 }
			 elseif ($F(text, "category name=Interchange") > 1)
