						if SQLCODE '= 0
						{			
								Do outFile.WriteLine( "EdifecsID: " _ sid _ "- Error in finding InterchangeSenderID, SQLCODE: " _ SQLCODE _ ", Name: " _tpLnkNm _ text _ ", TPs: " _ sender _ "->" _ receiver)
								QUIT							 
						}
						elseif (tpId = "")
						{
							Do outFile.WriteLine( "ID for TP is empty " _ sid)

						}
						set isaSender = tpId 
