				 if ($F(text, "SenderPartner") > 1)
				 {
					 set edifId =sender
				 }
				 else
				 {
					 set edifId = receiver
				 }

				 set colNm = $REPLACE($EXTRACT(text, $F(text, "Partner.cf."),  $F(text, "}") - 2), "_", "")
				 // Do outFile.WriteLine( colNm _ " for: " _ edifId)
				  set myquery = "SELECT " _ colNm _ " FROM IHC_ITF_ITFCOMMON_TPManage.CustomFields where EdicTpId = " _edifId
				    set tStatement = ##class(%SQL.Statement).%New()
					  set qStatus = tStatement.%Prepare(myquery)
					   if qStatus'=1 {write !, myquery _ " - %Prepare failed:" do $System.Status.DisplayError(qStatus) quit}
					  set rset = tStatement.%Execute()
					  while rset.%Next()
  						{
							set route = rset.%Get(colNm)
								if SQLCODE '= 0
								{			
										Do outFile.WriteLine( "EdifecsID: " _ edifId _ "- Error in finding CustomFields: " _ SQLCODE _ ", Name: " _tpLnkNm)
										QUIT							 
								}
								elseif (tpId = "")
								{
									Do outFile.WriteLine( "ID for CustomFields is empty " _ sid)

								}
								// Do outFile.WriteLine( " -- Routing: " _ route
  						}


			 }
			 elseif ($LOCATE(text, "CNIncrement|CNLastUsed|CNScope|CNType") > 0)
			 {

	    			if (getCN = 1)
	    			{

		    			// Do outFile.WriteLine( "Get CN values: " _ level _ text)
		    			set fldSep = $F(text, ">")
		    			set cnStr =  cnStr _ level _ $EXTRACT(text, $F(text, "name="),  fldSep - 2) _": "_$EXTRACT(text, fldSep, $F(text, "<", fldSep)-2) _ "; "
	    			}
			 }
			 elseif ($FIND(text, "SeverityConfig") > 0)
			 {
				 if ($F(text, "default=") > 0)
				 {
				 	set severity = $EXTRACT(text, $F(text, "default=") , $F(text, "esf;"))
				 	set severity = $EXTRACT(severity, $F(severity, "ESF/"), $F(severity, ".") -2)
				 }
			 }
			 elseif ($F(text, "category name=Acknowledgement") > 1  )
			 {
				 do {
					 set text = fileObj.ReadLine(,.sc, .eol)
					 // Do outFile.WriteLine( " -- ACK: " _ direction _", " _ level _ text _ " -> " _ getCN)
					 if $$$ISERR(sc) 
					 {
						 Do outFile.WriteLine( "End of File: " _sc _ ", " _ eol)
						 QUIT
					 } 
					 set line = line + 1
					 if ($F(text, "Type") > 0)
					 {
						 set type = $EXTRACT(text, $F(text, ">"), $F(text, "</") - 3)

					 }
					 elseif ($F(text, "Usage") > 0)
					 {
						 set usage = $EXTRACT(text, $F(text, ">"), $F(text, "</") - 3)

					 }
				 } while($F(text, "</category>") <= 0)
				 if (getCN = 1)
	    		 {
				 	// Do outFile.WriteLine( direction _", " _ level _ "Ack: " _ type _ ", " _ usage)

				 	if ($F(usage, "SenderPartner") > 1)
					 {
						 set edifId =sender
					 }
					 else
					 {
						 set edifId = receiver
					 }
					 set whenAck = ""
					 set defInd = $F(usage, "default=")
					 if (defInd > 0)
					 {
					 	set whenAck = $EXTRACT(usage, defInd , $F(usage, ";", defInd)-2)
					 }
					 else
					 {
					    set cusNm = $F(usage, "Partner.cf.")
					    if (cusNm <= 0)
					    {
						    set whenAck = usage
					    }
					    else
					    {
						 	set colNm = $REPLACE($EXTRACT(usage, cusNm,  $F(usage, "}") - 2), "_", "")

						  // Do outFile.WriteLine( " -- Check DB for " _colNm _ " for: " _ edifId)
						  set myquery = "SELECT " _ colNm _ " FROM IHC_ITF_ITFCOMMON_TPManage.CustomFields where EdicTpId = " _edifId
						    set tStatement = ##class(%SQL.Statement).%New()
							  set qStatus = tStatement.%Prepare(myquery)
							   if qStatus'=1 {write !, myquery _ " - %Prepare failed:" do $System.Status.DisplayError(qStatus) quit}
							  set rset = tStatement.%Execute()
							  while rset.%Next()
		  						{
									set whenAck = rset.%Get(colNm)
										if SQLCODE '= 0
										{			
												Do outFile.WriteLine( "EdifecsID: " _ edifId _ "- Error in finding CustomFields: " _ SQLCODE _ ", Name: " _tpLnkNm)
												QUIT							 
										}
										elseif (tpId = "")
										{
											Do outFile.WriteLine( "ID for CustomFields is empty " _ sid)

										}

		  						}
					 	}

		    		 }
		    		 // Do outFile.WriteLine( " --- ACK: " _ level _ type _": " _ whenAck _ "; ")
		    		 // set ackStr = ackStr _ type _": " _ whenAck _ "; "
		    		 set ackStr = ackStr _ $ZCONVERT(whenAck, "U") _ "; "

				  }
			 }
			 elseif ( (getCN = 1) && ($LOCATE(text, "Separator|Delimiter") > 1 ) )
			 {
				 set fldSep = $F(text, ">")
				 // Do outFile.WriteLine( " -*- Separator: "_  $EXTRACT(text, $F(text, "name="),  fldSep - 2) _": "_$EXTRACT(text, fldSep, $F(text, "<", fldSep)-2) _ "; ")
