					 // Do outFile.WriteLine( colNm _ " for: " _ edifId)
					  set myquery = "SELECT " _ colNm _ " FROM IHC_ITF_ITFCOMMON_TPManage.CustomFields where EdicTpId = " _edifId
					    set tStatement = ##class(%SQL.Statement).%New()
						  set qStatus = tStatement.%Prepare(myquery)
						   if qStatus'=1 {write !, myquery _ " - %Prepare failed:" do $System.Status.DisplayError(qStatus) quit}
						  set rset = tStatement.%Execute()
