					 set sepStr = sepStr _ $EXTRACT(text, $F(text, "name="),  fldSep - 2) _": "_$EXTRACT(text, fldSep, $F(text, "<", fldSep)-2) _ "; "
				 }

			 }
			 elseif ((trans = 835) && ($F(text, "BatchingMode835") > 1))
