								}
								elseif (tpId = "")
								{
									Do outFile.WriteLine( "ID for CustomFields is empty " _ sid)

								}
								set batch835 = colNm _":" _ ele
  						}


			 }
			 // --
		}
	 }
	 Do outFile.WriteLine( "Processed: " _ flNm)
	 DO fileObj.Close()
 } else
 {
